 [StructLayout(LayoutKind.Sequential)]struct ScrollInfo{public int Size,Mask,Min,Max,Page,Position,Track;}
 [DllImport("user32.dll")]static extern bool GetScrollInfo(IntPtr hwnd,int bar,ref ScrollInfo info);
 [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr hwnd,int msg,IntPtr wParam,IntPtr lParam);
 static int passed;
 static void Check(bool value,string message){if(!value)throw new Exception(message);passed++;}
 static object Field(object obj,string name)=>obj.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(obj);
 static object Call(object obj,string name,params object[] args)=>obj.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(obj,args);
 static void Snapshot(Form form,string path){Control content=form.Controls.OfType<TableLayoutPanel>().FirstOrDefault()??(Control)form.Controls.OfType<Panel>().First();var dock=content.Dock;form.Controls.Remove(content);try{content.Dock=DockStyle.None;content.Size=new Size(form.Width-24,form.Height-80);content.Visible=true;content.CreateControl();content.PerformLayout();using(var bitmap=new Bitmap(content.Width,content.Height)){content.DrawToBitmap(bitmap,new Rectangle(Point.Empty,content.Size));bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}finally{form.Controls.Add(content);content.Dock=dock;}}
 [STAThread]static void Main(string[] args){try{if(args.Contains("--scrollbar-only")){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);DossierPreferences.SuppressPersistenceForTests=true;DossierFeedback.MutedForTests=true;DossierMotion.SuppressForTests=true;RunScrollbars(args);}else Run(args);Console.WriteLine("PASS: "+passed+" data, export, preset, editor and undo checks.");}catch(Exception e){Console.Error.WriteLine(e);Environment.ExitCode=1;}}
 static void RunScrollbars(string[] args){
  if(!SystemInformation.HighContrast)using(var skinForm=new Form{Size=new Size(500,360)})using(var box=new TextBox{Dock=DockStyle.Fill,Multiline=true,WordWrap=false,ScrollBars=ScrollBars.Both,Text=string.Join("\r\n",Enumerable.Range(0,200).Select(i=>i+" "+new string('x',200)))}){
   var panel=new Panel{Dock=DockStyle.Fill};panel.Controls.Add(box);skinForm.Controls.Add(panel);StudioModule.Style(skinForm);Check(DossierScrollbars.IsAttached(box)&&DossierScrollbars.IsAttached(panel),"Custom scrollbar hook missing");
   string shot=Path.Combine(args.Length>1?args[1]:AppDomain.CurrentDomain.BaseDirectory,"scrollbars.png");Snapshot(skinForm,shot);using(var bitmap=new Bitmap(shot)){var accent=DossierTheme.Load().ColorFor("Accent");int count=0;for(int y=0;y<bitmap.Height;y++)for(int x=bitmap.Width-24;x<bitmap.Width;x++){var p=bitmap.GetPixel(x,y);if(Math.Abs(p.R-accent.R)<12&&Math.Abs(p.G-accent.G)<12&&Math.Abs(p.B-accent.B)<12)count++;}Check(count>5,"Scrollbar screenshot has no themed thumb pixels");}
   var before=new ScrollInfo{Size=Marshal.SizeOf(typeof(ScrollInfo)),Mask=0x17};GetScrollInfo(box.Handle,1,ref before);SendMessage(box.Handle,0x115,new IntPtr(7),IntPtr.Zero);var after=new ScrollInfo{Size=Marshal.SizeOf(typeof(ScrollInfo)),Mask=0x17};GetScrollInfo(box.Handle,1,ref after);Check(after.Position>before.Position,"Native vertical scrollbar no longer scrolls");
   var horizontal=new ScrollInfo{Size=Marshal.SizeOf(typeof(ScrollInfo)),Mask=0x17};GetScrollInfo(box.Handle,0,ref horizontal);SendMessage(box.Handle,0x114,new IntPtr(7),IntPtr.Zero);var horizontalAfter=new ScrollInfo{Size=Marshal.SizeOf(typeof(ScrollInfo)),Mask=0x17};GetScrollInfo(box.Handle,0,ref horizontalAfter);Check(horizontalAfter.Position>horizontal.Position,"Native horizontal scrollbar no longer scrolls");box.BorderStyle=BorderStyle.None;Snapshot(skinForm,shot);Check(DossierScrollbars.IsAttached(box),"Scrollbar skin detached on handle recreation");if(args.Length<2)File.Delete(shot);
  }
 }
